    public static function svg(string $name, string $class = 'size-5', ?string $strokeWidth = '1.5', string $attributes = ''): string
    {
        $attrs = 'class="'.e($class).'" aria-hidden="true"'.($attributes !== '' ? ' '.$attributes : '');

        if (isset(self::SOLID[$name])) {
            return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" '.$attrs.'><path d="'.self::SOLID[$name].'"/></svg>';
        }

        $paths = collect(preg_split('/ (?=M)/', self::OUTLINE[$name] ?? self::OUTLINE['sparkles']))
            ->map(fn ($d) => '<path stroke-linecap="round" stroke-linejoin="round" d="'.$d.'"/>')
            ->implode('');

        return '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="'.e((string) $strokeWidth).'" stroke="currentColor" '.$attrs.'>'.$paths.'</svg>';
    }
}
